<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$pdo=learning_pdo();$uid=learning_user_id();$d=json_decode(file_get_contents('php://input'),true)?:[];$mid=(int)($d['mock_id']??0);$answers=$d['answers']??[];
try{$s=$pdo->prepare("SELECT * FROM learning_mock_tests WHERE id=? AND is_published=1");$s->execute([$mid]);$m=$s->fetch();if(!$m)throw new RuntimeException('Mock test not found');$s=$pdo->prepare("SELECT q.id,q.marks FROM learning_mock_questions mq JOIN learning_questions q ON q.id=mq.question_id WHERE mq.mock_test_id=?");$s->execute([$mid]);$qs=$s->fetchAll();$score=0;$total=0;foreach($qs as $q){$total+=(int)$q['marks'];$oid=(int)($answers[(string)$q['id']]??0);$c=$pdo->prepare("SELECT is_correct FROM learning_options WHERE id=? AND question_id=?");$c->execute([$oid,$q['id']]);if((int)$c->fetchColumn())$score+=(int)$q['marks'];}$pct=$total?round($score*100/$total,2):0;$passed=$pct>=(int)$m['pass_percent'];$xp=$passed?(int)$m['xp']:0;$i=$pdo->prepare("INSERT INTO learning_mock_attempts(user_id,mock_test_id,score,total,percent,passed,xp_earned,finished_at) VALUES(?,?,?,?,?,?,?,NOW())");$i->execute([$uid,$mid,$score,$total,$pct,$passed?1:0,$xp]);$st=$pdo->prepare("INSERT INTO learning_user_stats(user_id,xp,mock_tests_passed) VALUES(?,?,?) ON DUPLICATE KEY UPDATE xp=xp+VALUES(xp),mock_tests_passed=mock_tests_passed+VALUES(mock_tests_passed)");$st->execute([$uid,$xp,$passed?1:0]);header('Content-Type:application/json');echo json_encode(['ok'=>true,'score'=>$score,'total'=>$total,'percent'=>$pct,'passed'=>$passed,'xp'=>$xp]);}catch(Throwable $e){http_response_code(500);header('Content-Type:application/json');echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}
